update app_state st set value=st.value||(select coalesce(jsonb_agg(a),'[]') from jsonb_array_elements('[{"sharedRoutine": true, "activeFrom": "2026-11-07", "assignedBy": "Dirección", "editableBy": ["APODERADA_LEGAL", "DIRECTOR", "GERENTE_GENERAL", "GERENTE_TIENDA"], "agendaPriority": 100, "evidence": "photo", "id": "exhibicion-manana-general", "name": "Rellenar exhibidores: sin espacios vacíos", "start": "09:30", "end": "10:00", "durationMinutes": 30, "area": "Operación y clientes", "ownerRoles": ["JEFE_AREA", "AUXILIAR"], "instructions": "Atender de inmediato a cada cliente; pausar y retomar esta actividad. Revisar toda la exhibición de tu área, reponer productos y registrar faltantes reales. Si no hay existencias, documentarlo y avisar al superior; no ocultar espacios sin resolver.", "excludeEmployeeIds": ["006", "008", "010"]}, {"sharedRoutine": true, "activeFrom": "2026-11-07", "assignedBy": "Dirección", "editableBy": ["APODERADA_LEGAL", "DIRECTOR", "GERENTE_GENERAL", "GERENTE_TIENDA"], "agendaPriority": 100, "evidence": "photo", "id": "exhibicion-manana-sabina-jan", "name": "Sabina y Jan: rellenar exhibidores", "start": "09:00", "end": "09:30", "durationMinutes": 30, "area": "Operación y clientes", "ownerRoles": ["JEFE_AREA"], "instructions": "Atender de inmediato a cada cliente; pausar y retomar esta actividad. Rellenar exhibidores y muestrarios de tu área; no dejar huecos. Documentar faltantes sin existencia y avisar al superior.", "employeeIds": ["006", "008"]}, {"sharedRoutine": true, "activeFrom": "2026-11-07", "assignedBy": "Dirección", "editableBy": ["APODERADA_LEGAL", "DIRECTOR", "GERENTE_GENERAL", "GERENTE_TIENDA"], "agendaPriority": 100, "evidence": "photo", "id": "exhibicion-manana-celina", "name": "Celina: rellenar exhibición", "start": "10:30", "end": "11:00", "durationMinutes": 30, "area": "Operación y clientes", "ownerRoles": ["JEFE_AREA"], "instructions": "Atender de inmediato a cada cliente; pausar y retomar esta actividad. Reponer la exhibición de electrodomésticos completa y reportar cualquier espacio sin producto o falta de existencias.", "employeeIds": ["010"]}, {"sharedRoutine": true, "activeFrom": "2026-11-07", "assignedBy": "Dirección", "editableBy": ["APODERADA_LEGAL", "DIRECTOR", "GERENTE_GENERAL", "GERENTE_TIENDA"], "agendaPriority": 100, "evidence": "photo", "id": "exhibicion-tarde-general", "name": "Segunda reposición de exhibidores", "start": "16:00", "end": "17:00", "durationMinutes": 60, "area": "Operación y clientes", "ownerRoles": ["JEFE_AREA", "AUXILIAR"], "instructions": "Atender de inmediato a cada cliente; pausar y retomar esta actividad. Recorrer de nuevo el área, rellenar cada hueco, mantener precios visibles y reportar faltantes sin existencia. Dejar evidencia del resultado."}, {"sharedRoutine": true, "activeFrom": "2026-11-07", "assignedBy": "Dirección", "editableBy": ["APODERADA_LEGAL", "DIRECTOR", "GERENTE_GENERAL", "GERENTE_TIENDA"], "agendaPriority": 100, "evidence": "signature", "id": "citlali-redes-diarias", "name": "Citlali: publicar y planear redes sociales", "start": "10:00", "end": "11:00", "durationMinutes": 60, "area": "Operación y clientes", "ownerRoles": ["JEFE_AREA"], "instructions": "Atender de inmediato a cada cliente; pausar y retomar esta actividad. 10:00–10:30 publicar diariamente el material aprobado en las redes sociales. Dentro del mismo bloque, hasta las 11:00, planear el material del día siguiente: productos, mensaje, precio vigente, tomas, guion y pendientes. Registrar enlaces a publicaciones y referencia del plan. Miércoles: pedido de plomería 09:00–09:30 antes de este bloque.", "employeeIds": ["015"]}, {"sharedRoutine": true, "activeFrom": "2026-11-07", "assignedBy": "Dirección", "editableBy": ["APODERADA_LEGAL", "DIRECTOR", "GERENTE_GENERAL", "GERENTE_TIENDA"], "agendaPriority": 100, "evidence": "signature", "id": "citlali-audiovisual", "name": "Citlali: realizar material audiovisual", "start": "17:00", "end": "18:00", "durationMinutes": 60, "area": "Operación y clientes", "ownerRoles": ["JEFE_AREA"], "instructions": "Atender de inmediato a cada cliente; pausar y retomar esta actividad. Martes, miércoles y viernes: realizar fotografías, tomas, grabación o edición conforme al plan y guardar referencia del material para publicación. Salida programada 19:00 estos días. Siempre atender primero al cliente.", "employeeIds": ["015"], "weekdays": [2, 3, 5]}, {"sharedRoutine": true, "activeFrom": "2026-11-07", "assignedBy": "Dirección", "editableBy": ["APODERADA_LEGAL", "DIRECTOR", "GERENTE_GENERAL", "GERENTE_TIENDA"], "agendaPriority": 20, "evidence": "signature", "id": "matriz-jefes-operacion-diaria", "name": "Atención inmediata, mercancía e inventario del área", "start": "12:30", "end": "16:00", "durationMinutes": 210, "area": "Operación y clientes", "ownerRoles": ["JEFE_AREA"], "instructions": "Atender de inmediato a cada cliente; pausar y retomar esta actividad. Atender primero al cliente; usar los intervalos disponibles para revisar mercancía, precios, inventario, exhibición y pendientes del área. Respetar tu comida y turno configurados; no dejar un cliente esperando por una actividad programada. Mantener mostradores limpios, libres de mercancía; sólo promociones o muestrarios autorizados.", "branch": "Matriz"}, {"sharedRoutine": true, "activeFrom": "2026-11-07", "assignedBy": "Dirección", "editableBy": ["APODERADA_LEGAL", "DIRECTOR", "GERENTE_GENERAL", "GERENTE_TIENDA"], "agendaPriority": 50, "evidence": "signature", "id": "matriz-jefes-cierre-a", "name": "Cerrar pendientes, mostradores y reporte antes de salir", "start": "17:00", "end": "17:30", "durationMinutes": 30, "area": "Operación y clientes", "ownerRoles": ["JEFE_AREA"], "instructions": "Atender de inmediato a cada cliente; pausar y retomar esta actividad. Dejar mostradores limpios y listos, cerrar actividades con evidencias y registrar pendientes. En la última jornada antes de descansar, entregar el reporte semanal con evidencias antes de marcar salida.", "employeeIds": ["008", "009", "010"], "branch": "Matriz"}, {"sharedRoutine": true, "activeFrom": "2026-11-07", "assignedBy": "Dirección", "editableBy": ["APODERADA_LEGAL", "DIRECTOR", "GERENTE_GENERAL", "GERENTE_TIENDA"], "agendaPriority": 50, "evidence": "signature", "id": "matriz-citlali-cierre-a", "name": "Citlali: cerrar actividades y reporte", "start": "17:00", "end": "17:30", "durationMinutes": 30, "area": "Operación y clientes", "ownerRoles": ["JEFE_AREA"], "instructions": "Atender de inmediato a cada cliente; pausar y retomar esta actividad. Cerrar actividades y documentar pendientes; antes del descanso entregar el reporte semanal con evidencias.", "employeeIds": ["015"], "branch": "Matriz", "weekdays": [1, 4, 6, 0]}, {"sharedRoutine": true, "activeFrom": "2026-11-07", "assignedBy": "Dirección", "editableBy": ["APODERADA_LEGAL", "DIRECTOR", "GERENTE_GENERAL", "GERENTE_TIENDA"], "agendaPriority": 50, "evidence": "signature", "id": "matriz-jefes-cierre-b", "name": "Orden de área y cierre de actividades", "start": "18:00", "end": "19:00", "durationMinutes": 60, "area": "Operación y clientes", "ownerRoles": ["JEFE_AREA"], "instructions": "Atender de inmediato a cada cliente; pausar y retomar esta actividad. Dejar mostradores listos, documentación y material en orden, entregar pendientes y completar el reporte semanal cuando corresponda. Citlali: este bloque largo aplica sólo martes, miércoles y viernes; los demás días rige su salida habitual.", "employeeIds": ["006", "012", "015"], "branch": "Matriz", "weekdays": [2, 3, 5]}, {"sharedRoutine": true, "activeFrom": "2026-11-07", "assignedBy": "Dirección", "editableBy": ["APODERADA_LEGAL", "DIRECTOR", "GERENTE_GENERAL", "GERENTE_TIENDA"], "agendaPriority": 75, "evidence": "signature", "id": "sabina-cierre-redes", "name": "Sabina: cerrar mensajes de redes y pendientes del día", "start": "17:00", "end": "17:30", "durationMinutes": 30, "area": "Operación y clientes", "ownerRoles": ["JEFE_AREA"], "instructions": "Durante todo el turno responder mensajes de todas las redes sociales, atendiendo primero al cliente presente. Al cierre registrar las redes revisadas, lo respondido y los mensajes pendientes con motivo, sin copiar datos privados de clientes. Dejar mostradores limpios, cerrar actividades y entregar el reporte semanal cuando corresponda.", "employeeIds": ["008"], "branch": "Matriz", "weekdays": [0, 1, 2, 3, 4, 5, 6]}]'::jsonb)a where not exists(select 1 from jsonb_array_elements(st.value)b where b->>'id'=a->>'id')),updated_at=now() where key='xoxo.activitySchedules';
update app_state st set value=(select jsonb_agg(case when c->>'id'='014' then c||'{"workdays":[5,6,0]}'::jsonb when c->>'id'='015' then c||'{"weekdayShiftEnds":{"2":"19:00","3":"19:00","5":"19:00"}}'::jsonb else c end) from jsonb_array_elements(st.value)c),updated_at=now() where key='xoxo.collaborators';
create or replace function resolve_activity_routine(rows jsonb) returns jsonb language plpgsql immutable set search_path=public as $$
declare row jsonb;block jsonb;part jsonb;parts jsonb;next_parts jsonb;result jsonb:='[]';s text;e text;a text;z text;own_rank integer;other_rank integer;
begin
 for row in select value from jsonb_array_elements(rows) loop
  if lower(row->>'area') like '%aseo%' then result:=result||jsonb_build_array(row);continue;end if;
  own_rank:=coalesce((row->>'agendaPriority')::integer,case when row->>'id'='matriz-invewin-configuracion' then 90 when row->>'sharedRoutine'='true' then 30 else 0 end);parts:=jsonb_build_array(jsonb_build_array(row->>'start',row->>'end'));
  for block in select value from jsonb_array_elements(rows) where value->>'id'<>row->>'id' and lower(value->>'area') not like '%aseo%' loop
   other_rank:=coalesce((block->>'agendaPriority')::integer,case when block->>'id'='matriz-invewin-configuracion' then 90 when block->>'sharedRoutine'='true' then 30 else 0 end);if other_rank<=own_rank then continue;end if;
   a:=block->>'start';z:=block->>'end';next_parts:='[]';
   for part in select value from jsonb_array_elements(parts) loop s:=part->>0;e:=part->>1;
    if z<=s or a>=e then next_parts:=next_parts||jsonb_build_array(part);else
     if a>s then next_parts:=next_parts||jsonb_build_array(jsonb_build_array(s,least(e,a)));end if;
     if z<e then next_parts:=next_parts||jsonb_build_array(jsonb_build_array(greatest(s,z),e));end if;
    end if;
   end loop;parts:=next_parts;
  end loop;
  for part in select value from jsonb_array_elements(parts) loop s:=part->>0;e:=part->>1;
   result:=result||jsonb_build_array(row||jsonb_build_object('id',case when s=row->>'start' and e=row->>'end' then row->>'id' else (row->>'id')||'~'||replace(s,':','')||'-'||replace(e,':','') end,'start',s,'end',e,'durationMinutes',extract(epoch from(e::time-s::time))/60));
  end loop;
 end loop;return result;
end $$;
revoke all on function resolve_activity_routine(jsonb) from public,anon,authenticated;
do $$declare definition text;begin
 definition:=pg_get_functiondef('staff_capture_today_plans()'::regprocedure);
 if position('excludeEmployeeIds' in definition)=0 then definition:=replace(definition,$old$where st.key='xoxo.activitySchedules' and $old$,$new$where st.key='xoxo.activitySchedules' and not coalesce(a->'excludeEmployeeIds','[]') ? person.employee_number and $new$);end if;
 if position('resolve_activity_routine' in definition)=0 then definition:=replace(definition,$old$  if branch<>'Sucursal Centro' then$old$,$new$  routine:=resolve_activity_routine(routine);
  if branch<>'Sucursal Centro' then$new$);end if;execute definition;
end $$;
alter table matriz_order_roster add column if not exists start_time text not null default '10:00';
alter table matriz_order_roster add column if not exists end_time text not null default '11:00';
update matriz_order_roster set start_time='09:00',end_time='09:30' where weekday=3 and lead_id='015';
do $$declare definition text;begin
 definition:=pg_get_functiondef('matriz_orders_reconcile(date)'::regprocedure);
 if position('r.start_time' in definition)=0 then definition:=replace(definition,$old$'start','10:00','end','11:00'$old$,$new$'start',case when followup then '10:00' else r.start_time end,'end',case when followup then '11:00' else r.end_time end$new$);execute definition;end if;
 definition:=pg_get_functiondef('matriz_order_action(text,text,text,text)'::regprocedure);
 definition:=replace(definition,$old$if clock<'10:00' then raise exception 'El pedido inicia a las 10:00'; end if;$old$,$new$if clock<coalesce(r.payload->>'start','10:00') then raise exception 'El pedido inicia a las %',coalesce(r.payload->>'start','10:00'); end if;$new$);
 definition:=replace(definition,$old$'onTime',clock<='11:00'$old$,$new$'onTime',clock<=coalesce(r.payload->>'end','11:00')$new$);execute definition;
end $$;
create or replace function cleaning_exit_time(person text,day date) returns text language sql stable security definer set search_path=public as $$
 select coalesce((select w->>'end' from app_state st cross join lateral jsonb_array_elements(st.value)w where st.key='xoxo.workLocations' and w->>'employeeId'=person and w->>'date'=day::text limit 1),
 (select c#>>array['weekdayShiftEnds',extract(dow from day)::integer::text] from app_state st cross join lateral jsonb_array_elements(st.value)c where st.key='xoxo.collaborators' and c->>'id'=person limit 1),
 (select sh->>'end' from app_state st cross join lateral jsonb_array_elements(st.value)sh where st.key='xoxo.shiftConfigs' and sh->>'key'=(select c->>'shift' from app_state cs cross join lateral jsonb_array_elements(cs.value)c where cs.key='xoxo.collaborators' and c->>'id'=person limit 1) limit 1))
$$;
revoke all on function cleaning_exit_time(text,date) from public,anon,authenticated;
notify pgrst,'reload schema';commit;
